import numpy as np

def problem(x: np.ndarray) -> float:
    """Combines a quadratic bowl with sinusoidal modulation and pairwise interactions.

    f(x) = sum(i * x_i^2) + 0.5 * sum(sin(3*x_i)) + 0.1 * sum(x_i * x_j for i < j) + 0.224 * x[0]
    """
    n = len(x)
    result = 0.0
    for i in range(n):
        result += (i+1) * x[i]**2  # Quadratic bowl with increasing coefficients

    for i in range(n):
        result += 0.5 * np.sin(3 * x[i]) # Sinusoidal modulation


    for i in range(n):
        for j in range(i + 1, n):
            result += 0.1 * x[i] * x[j]  # Pairwise interactions

    result += 0.224 * x[0] # Adding some skew via linear scaling of the first variable

    return result
